  "decode.kind.version.title": "Versión",
  "decode.kind.version.desc": "Generación / versión de lanzamiento de la familia.",
  "decode.kind.params.title": "Número de parámetros",
  "decode.kind.params.desc": "Parámetros totales (miles de millones). Determina la calidad y la VRAM — más grande = más capaz, pero más pesado.",
  "decode.kind.paramsM.title": "Número de parámetros (M)",
  "decode.kind.paramsM.desc": "Millones de parámetros — un modelo pequeño / apto para edge.",
  "decode.kind.moe.title": "Mezcla de expertos",
  "decode.kind.moe.desc": "expertos × tamaño de cada uno (p. ej., 8x7B). Solo unos pocos expertos se ejecutan por token (cómputo rápido), pero TODOS los expertos deben caber en la VRAM.",
  "decode.kind.moeActive.title": "MoE — parámetros activos",
  "decode.kind.moeActive.desc": "Parámetros activos por token (p. ej., A3B = 3B activos). Cómputo ≈ parámetros activos; VRAM ≈ parámetros totales.",
  "decode.kind.quantAWQ.title": "Cuantización · AWQ",
  "decode.kind.quantAWQ.desc": "Activation-aware Weight Quantization (~4 bits). ~4× más pequeño, rápido en GPU, pequeña pérdida de exactitud.",
  "decode.kind.quantGPTQ.title": "Cuantización · GPTQ",
  "decode.kind.quantGPTQ.desc": "Cuantización GPTQ de pesos a 4 bits. Pequeño y rápido en GPU; ligera pérdida de exactitud.",
  "decode.kind.quantGGUF.title": "Formato · GGUF",
  "decode.kind.quantGGUF.desc": "Formato de llama.cpp — funciona en CPU y GPU con muchos niveles de cuantización (Q4…Q8). Ideal para uso local / Mac.",
  "decode.kind.quantFP8.title": "Cuantización · FP8",
  "decode.kind.quantFP8.desc": "Punto flotante de 8 bits. ~2× más pequeño que BF16, casi sin pérdidas, rápido en GPU modernas (Hopper/Blackwell/MI300).",
  "decode.kind.quantNVFP4.title": "Cuantización · NVFP4 / MXFP4",
  "decode.kind.quantNVFP4.desc": "Punto flotante de 4 bits (NVFP4 en Blackwell, MXFP4 p. ej. en gpt-oss). ~4× más pequeño y con mejor exactitud que INT4.",
  "decode.kind.quantINT.title": "Cuantización · INT4/INT8",
  "decode.kind.quantINT.desc": "Cuantización entera (4 u 8 bits). Más pequeño y más rápido; INT4 sacrifica algo de exactitud.",
  "decode.kind.quantWA.title": "Cuantización · bits W/A",
  "decode.kind.quantWA.desc": "Ancho de bits de los pesos (W) y las activaciones (A) — p. ej., W4A16 = pesos de 4 bits, activaciones de 16 bits.",
  "decode.kind.quantBnb.title": "Cuantización · bitsandbytes",
  "decode.kind.quantBnb.desc": "4 bits / 8 bits al vuelo (bitsandbytes). Fácil de cargar, bueno para VRAM limitada.",
  "decode.kind.quantDynamic.title": "Cuantización · dinámica",
  "decode.kind.quantDynamic.desc": "Cuantización dinámica — escalas calculadas en tiempo de ejecución (a menudo junto con FP8).",
  "decode.kind.precision.title": "Precisión",
  "decode.kind.precision.desc": "Precisión nativa de los pesos (BF16/FP16 = 2 bytes, FP32 = 4). Calidad completa, tamaño máximo.",
  "decode.kind.instruct.title": "Ajustado para instrucciones",
  "decode.kind.instruct.desc": "Con ajuste fino para seguir instrucciones / chatear. Úsalo para asistentes y para la mayoría de las tareas.",
  "decode.kind.chat.title": "Ajustado para chat",
  "decode.kind.chat.desc": "Optimizado para conversaciones de varios turnos.",
  "decode.kind.base.title": "Modelo base",
  "decode.kind.base.desc": "Solo preentrenado — NO ajustado para instrucciones. Sirve para ajuste fino, no para chatear tal cual.",
  "decode.kind.coder.title": "Especializado en código",
