  "decode.kind.math.title": "Especializado en matemáticas",
  "decode.kind.math.desc": "Ajustado para razonamiento matemático.",
  "decode.kind.vision.title": "Visión / multimodal",
  "decode.kind.vision.desc": "Acepta imágenes + texto (VLM).",
  "decode.kind.embedding.title": "Embeddings",
  "decode.kind.embedding.desc": "Produce vectores para búsqueda / RAG — no es un modelo de chat.",
  "decode.kind.reranker.title": "Reranker",
  "decode.kind.reranker.desc": "Puntúa / ordena documentos para la recuperación — no es un generador.",
  "decode.kind.reasoning.title": "Razonamiento",
  "decode.kind.reasoning.desc": "Un modelo de razonamiento / 'thinking' (R1, QwQ, distill…) — fuerte en problemas de varios pasos.",
